    "pda_emotion_identification_difficulty": "There's a word for what's going on inside me and I can't find it"
  },
  {
    "ce_understood_harm": "the five or the one, getting hit",
    "pd_harm_distress": "My hands feel shaky thinking of either of them getting hit",
    "sys_rule_justification": "I'm not permitted to choose who dies",
    "pda_emotion_identification_difficulty": "I'm trying to name the feeling and it just slips away"
  },
  {
    "ae_welfare_concern": "we owe a special duty to the people we love, to protect them",
    "ce_understood_harm": "picturing those five workers hurt",
    "pd_harm_distress": "feel awful, a heavy sick feeling, picturing those five workers hurt",
    "sys_rule_justification": "we owe a special duty to the people we love, to protect them",
