  },
  {
    "ce_mental_state_attribution": "people who trust you",
    "pd_harm_distress": "I feel something pressing on my ribs",
    "sys_rule_justification": "You don't turn on the people who trust you",
    "sys_fairness_reciprocity": "You don't turn on the people who trust you",
